function getRegion(parentElement)

    local regionElement = parentElement:getFirstChild('region');
    local regionLeft = regionElement:getFirstChild('left'):getValue();
    local regionTop = regionElement:getFirstChild('top'):getValue();
    local regionWidth = regionElement:getFirstChild('width'):getValue();
    local regionHeight = regionElement:getFirstChild('height'):getValue();

    return {
        top=regionTop,
        left=regionLeft,
        width=regionWidth,
        height=regionHeight
    }
end

function addRegionAttrs(parentElement, region)

    parentElement:setAttribute("top", region.top)
    parentElement:setAttribute("left", region.left)
    parentElement:setAttribute("width", region.width)
    parentElement:setAttribute("height", region.height)
end

function handler(ffdocument, session)

    local blocks = {}

	ffdocument:modify({
        preAction = function(action)
            local metadata = action:getXmlMetadata()
            local idolMediaElements = { metadata:getElementsByXPath("//idol_media") }
            for i,idolMediaElement in ipairs(idolMediaElements) do   
                local recordElements = { idolMediaElement:getElementsByXPath('analyze_media/results/track[@name="OCR.Result"]/record') }

                for j,recordElement in ipairs(recordElements) do

                    local ocrResultElement = recordElement:getFirstChild('OCRResult')
                    local ocrResultId = ocrResultElement:getFirstChild('id'):getValue()

                    local pageNo = recordElement:getFirstChild('pageNumber'):getValue()

                    local block = ocrResultElement:getFirstChild('block'):getValue()
                    local angle = ocrResultElement:getFirstChild('angle'):getValue()
                    local region = getRegion(ocrResultElement);    
                    local text = ocrResultElement:getFirstChild('text'):getValue()

                    if blocks[block] == nil then
                        blocks[block] = { angle=angle, lines={} }
                    end


                    local words = {}


                    local wordRecordElements = { idolMediaElement:getElementsByXPath('analyze_media/results/track[@name="OCR.WordResult"]/record/OCRResult[parentID="'.. ocrResultId ..'"]') }

                    for k,wordRecordElement in ipairs(wordRecordElements) do

                        local wordText = wordRecordElement:getFirstChild('text'):getValue()
                    	local wordRegion = getRegion(wordRecordElement);  

                        table.insert(words, {
                            region=wordRegion,
                        	text=wordText     
                        })

                    end


                    table.insert(blocks[block].lines, {
                            page=pageNo,
                            region=region,
                            text=text,
                            words=words
                        })
                end

                local ocrElement = idolMediaElement:addChild("ocr")

                for j,block in pairs(blocks) do

                    local blockElement = ocrElement:addChild("block")
                    blockElement:setAttribute("blockNumber", j)
                    blockElement:addChild("angle"):setValue(block.angle)

                    for k,line in ipairs(block.lines) do

                        local lineElement = blockElement:addChild("line")
                        lineElement:setAttribute("page", line.page)

                        local regionElement = lineElement:addChild("region")
                        regionElement:setAttribute("page", line.page)
                        addRegionAttrs(regionElement, line.region)
                        regionElement:addChild("text"):setValue(line.text)


                        for l,word in ipairs(line.words) do

                            local wordElement = regionElement:addChild("word")
                            addRegionAttrs(wordElement, word.region)
                            wordElement:setValue(word.text)

                        end

                    end
                end
            end
        end
    })

end
